// Loop over input items and add a new field called 'myNewField' to the JSON of each one
let messages = $input.first().json.messages.split(";")
let query = "SELECT imv_codigo, titulo, finalidade, preco, condominio_preco, cidade, quartos, suites, banheiros, tipo, bairro, vagas_carro, aceita_pet, mobiliado, imagem_principal FROM pierre.imoveis WHERE imv_codigo IN (";

for (const [idx, imv] of messages.entries()) {
  if (imv.startsWith("IMV-")) {
    if (idx === messages.length - 1) {
      query += `'${imv}');`;
    } else {
      query += `'${imv}', `;
    }
  }
}


return {query};
